"重跑等待确认(秒)": "انتظار تأكيد الإعادة (ثانية)",
"重跑等待确认需为 {min}-{max} 的整数(秒)": "يجب أن تكون مدة انتظار تأكيد الإعادة عدداً صحيحاً بين {min} و{max} (بالثواني)",
"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "مدة انتظار نوافذ تأكيد الإعادة («هل تعيد التشغيل؟» وغيرها)، الافتراضي 60 ثانية: إذا انتهى العد التنازلي دون رد يُعتمد الخيار الافتراضي تلقائياً (عادةً «إعادة التشغيل») فلا يتعطل خط الإنتاج بانتظار أحد. زيادة القيمة تمنحك وقتاً أطول للبتّ، مقابل انتظار أطول عند النافذة في غياب المتابعة؛ ويبقى الانتظار الأقصر الذي يحدده الوكيل صراحةً سارياً لكنه لا يتجاوز هذه القيمة أبداً. نوافذ التوقيع (التوقيع اليدوي لبوابات H) لا تعدّ تنازلياً ولا تتأكد تلقائياً، فهي غير متأثرة. إعداد عام؛ يسري على التأكيدات الصادرة بعد الحفظ.",
"⚙️ Agent 高级设置": "⚙️ إعدادات Agent المتقدمة",
"重跑次数": "عدد مرات الإعادة",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "الحد الأقصى لعدد مرات إعادة التشغيل / إعادة التوليد التلقائية للوكلاء، الافتراضي 0: عند فشل تقييم القبول أو مراجعة الجودة أو الفحص الآلي يعيد المنتج العمل تلقائياً مع ملاحظات لإعادة إنجازه؛ وعند فشل توليد الفيديو/الصورة في الفحص الآلي تتم إعادة التوليد تلقائياً. إذا بلغت المهمة نفسها هذا العدد وما زالت تفشل، تُصعَّد إلى المستخدم للبت بدلاً من المحاولة مجدداً؛ القيمة 0 تعطّل الإعادة التلقائية كلياً (الفشل الأول يُصعَّد فوراً). إعداد عام يُحقن في جميع الوكلاء عبر موجّه التشغيل ويتجاوز «3 مرات كحد أقصى» المثبّت في وثائق سير العمل؛ يسري على التشغيلات التي تبدأ بعد الحفظ.",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "يجب أن يكون عدد مرات الإعادة عدداً صحيحاً بين 0 و{max} (0 = بلا إعادة تلقائية)",
"轮次上限": "حد الأدوار",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "الحد الأقصى لعدد أدوار محادثة المحرك ضمن أمر عمل واحد، الافتراضي 250: يسري فقط على محركي claude و grok (معامل ‎--max-turns في الوضع headless؛ إغفاله يعني بلا حدود — هذه البوابة موضوعة لمنع الحلقات الجامحة). محركات codex/pi/opencode لا تملك هذا المعامل ولا تتأثر؛ ويستخدم deepagents حد التكرار الخاص بإطاره. عند بلوغ الحد يُقطع المحرك فورًا دون إمكانية الاستئناف — لا يُظهر الإيصال سوى رمز الخروج 1؛ تبقى المخرجات المحفوظة لكن يغيب التحقق والإيصال. في محطات الحجم الكبير (الانتقاء لكل مجموعة، القصّ الدفعي) يجعل أمرٌ يغطي عشرات المجموعات 100 دورة غير كافية إطلاقًا؛ إن استمر بلوغ الحد فقلّل أولًا عرض الدفعة ثم ارفع هذه القيمة. إعداد عام؛ يسري على التشغيلات التي تبدأ بعد الحفظ.",
"轮次上限需为 {min}-{max} 的整数": "يجب أن يكون حد الأدوار عددًا صحيحًا بين {min} و {max}",
"思考深度": "عمق التفكير",
"引擎默认": "الافتراضي للمحرك",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "إعداد موحّد لعمق التفكير (Thinking Effort)، الافتراضي «الافتراضي للمحرك»: عند الإسناد يُترجم إلى معامل شدة الاستدلال الخاص بكل محرك — claude → ‎--effort، codex → model_reasoning_effort (لا يوجد max؛ يُستخدم xhigh)، pi → ‎--thinking، opencode → ‎--variant (يُتجاهل إذا لم يكن للنموذج هذا المستوى)، grok → --reasoning-effort (بدون max؛ يُحوَّل إلى xhigh)، deepagents → reasoning_effort (قنوات السحابة/OpenRouter فقط؛ لا يُرسل للنماذج المحلية)؛ لا يملك kimi CLI معاملاً مماثلاً ولا يتأثر. كلما زاد العمق زاد الاستقرار لكن يصبح أبطأ ويستهلك رموزاً أكثر؛ «الافتراضي للمحرك» لا يمرّر شيئاً ويحتفظ بإعداد كل محرك الخاص (مثل effortLevel في ~/.claude/settings.json و model_reasoning_effort في ~/.codex/config.toml). إعداد عام لجميع الوكلاء، يسري على التشغيلات التي تبدأ بعد الحفظ.",
"条件": "مشروطة",
