"——与主画幅不同画幅的平台(如主画幅选 16:9 时的 TikTok/抖音)在发布期由 platform-adapter 从母版裁切适配,不重新生成视频;语言约束剧本/台词/旁白/字幕/配音/发布物料(给生成模型的英文 prompt 不受影响);草稿分辨率用于迭代/待审版本,成片分辨率是审核确认后终稿的目标分辨率——与草稿档不同时默认由超分(upscale)得到,不重新生成;分辨率越高视频生成费用越高(4K 仅 Seedance 2.0 标准版支持)。": "— المنصات ذات نسبة أبعاد مختلفة عن النسبة الرئيسية (مثل TikTok/Douyin عند اختيار 16:9 كنسبة رئيسية) يكيّفها platform-adapter بالقص من النسخة الأم في مرحلة النشر دون إعادة توليد الفيديو؛ اللغة تقيّد السيناريو/الحوار/السرد/الترجمة/التعليق الصوتي/مواد النشر (لا تتأثر prompt الإنجليزية المرسلة إلى نماذج التوليد)؛ دقة المسودة تُستخدم للنسخ التكرارية/قيد المراجعة، ودقة النسخة النهائية هي الدقة المستهدفة للنسخة المعتمدة بعد المراجعة — وإذا اختلفت عن دقة المسودة تُستخرج افتراضيًا بالترقية (upscale) دون إعادة توليد؛ كلما ارتفعت الدقة زادت تكلفة توليد الفيديو (4K مدعومة فقط في Seedance 2.0 النسخة القياسية).",
