"启用后按流程产出旁白稿与旁白配音轨;关闭=约定全片不出现任何旁白,叙事全部由画面与对白承担。仅控制旁白者叙述;人物画外/V.O. 由「声画分离」控制": "عند التفعيل يُنتَج نص التعليق الصوتي ومساره الصوتي وفق سير العمل؛ وعند التعطيل يُتَّفق على خلوّ الفيلم بأكمله من أي تعليق صوتي — تُروى القصة بالصورة والحوار فقط। يتحكم فقط في سرد الراوي؛ أما سطور الشخصيات خارج الكادر/V.O. فيحكمها «فصل الصوت عن الصورة»",
