",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": "، تُرفق مع الرسالة في كل مرة يوقظ فيها التشغيل التلقائي المنتجَ العام، فلا تضيع حتى بعد إعادة فتح الجلسة؛ مناسبة للقيود طويلة الأمد ويُفضَّل صياغتها بشكل شرطي (مثال: 「قبل اكتمال جميع نصوص الحلقات ep01-ep10، لا تُوزَّع أوامر عمل من نوع التصميم」)؛ اتركها فارغة كي لا يُرفق شيء",
"在 ep01-ep10 剧本全部完成前,不派设定类工单": "قبل اكتمال جميع نصوص الحلقات ep01-ep10، لا تُوزَّع أوامر عمل من نوع التصميم",
