"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "زمن الخمول: يُجرى فحص دوري كل هذه المدة، ولا تُرسل رسالة فحص الحالة إلا إذا كان خط الإنتاج خاملًا (لا مهام جارية ولا عناصر بانتظار التأكيد)، الافتراضي 5 دقائق. العتبة: إذا بلغ استهلاك جلسة نافذة الـ 5 ساعات للمحرك الساري لدى المنتج العام (claude/codex) هذه القيمة، لا تُرسل الرسالة في هذه الجولة؛ وإذا تعذّرت قراءة الاستهلاك يُسمح بالإرسال. كلاهما إعداد عام يسري على جميع المشاريع (المفتاح في زر 🤖 بلوحة التشغيل، مستقل لكل مشروع)",
