"获取 Key:": "احصل على المفتاح هنا:",
"配置好的用量/余额显示在右栏「资源消耗」面板,每 10 分钟自动刷新;顶栏当前引擎的用量会自动显示(选 pi 显示 codex 用量,因其常配 ChatGPT 订阅),上方开关开启后则不随引擎切换、始终显示;所有 Key 仅保存在本机 webui/state.json,不会上传": "يظهر الاستخدام/الرصيد المهيأ في لوحة «استهلاك الموارد» ويُحدّث تلقائيًا كل 10 دقائق؛ يُعرض استهلاك المحرك المحدد حاليًا في الشريط العلوي تلقائيًا (اختيار pi يعرض استهلاك codex لأن pi يعتمد عادةً على اشتراك ChatGPT)؛ ومع تفعيل المفاتيح أعلاه يبقى العرض دائمًا بغض النظر عن المحرك المختار؛ تُحفظ جميع المفاتيح محليًا فقط في webui/state.json ولا تُرفع أبدًا",
