"(私域虚拟人像素材库的前置条件)。": "(شرط مسبق لمكتبة الصور الافتراضية الخاصة).",
"在火山引擎控制台": "في وحدة تحكم Volcano Engine افتح",
"API 访问密钥管理": "إدارة مفاتيح الوصول API",
"创建并获取 Access Key / Secret Key(IAM 密钥,非 ark- 开头的方舟 API Key),填入下方并保存。": "أنشئ واحصل على Access Key / Secret Key (بيانات IAM، وليست مفتاح Ark API الذي يبدأ بـ ark-)، ثم أدخلها أدناه واحفظ.",
"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "بعد النقر على «تفعيل»، أدر الأصول المسجلة أدناه؛ ستظهر لكل صورة في معاينة الشخصيات زر «تسجيل»، وعند إعادة توليد المجموعة تُرسل الصور المرجعية المسجلة (Active) تلقائيًا كـ URI أصل (asset://المعرف).",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "ملاحظة: التسجيل يخضع لمراجعة غير متزامنة (Processing → Active/Failed)؛ فقط الأصول بحالة Active تصلح لتوليد الفيديو. تُعزل الأصول حسب «مشروع» Ark — يجب أن يطابق ProjectName أدناه مشروع مفتاح Ark API المستخدم لتوليد الفيديو في صفحة نماذج التوليد (الافتراضي default).",
"🔑 密钥与开关": "🔑 المفاتيح والتفعيل",
"Access Key / Secret Key 留空时,自动使用「⚙️ 设置 → 文件托管 → 火山引擎 TOS」已配置的 AK/SK(或环境变量 TOS_ACCESS_KEY/TOS_SECRET_KEY)。": "إذا تُركت Access Key / Secret Key فارغة، تُستخدم تلقائيًا AK/SK المهيأة في ⚙️ الإعدادات → استضافة الملفات → Volcano TOS (أو متغيرات البيئة TOS_ACCESS_KEY/TOS_SECRET_KEY).",
