"本集生效的视频渠道/模型/提示词技能:三个下拉可直接为本集切换(默认都跟随全局;全局在控制台「生成模型」/「模型限制」修改);个别组可用组卡「🎛 模型」单独指定,组级优先": "قناة / نموذج / مهارة موجّه الفيديو السارية لهذه الحلقة: القوائم الثلاث تبدّلها مباشرة لهذه الحلقة (الافتراضي أن تتبع كلها الإعداد العام؛ يُغيَّر العام من صفحة نماذج التوليد / حدود النموذج في لوحة التحكم)؛ ما زال بإمكان كل مجموعة التجاوز عبر زر 🎛 النموذج في بطاقتها، وتجاوز المجموعة له الأولوية",
