"⚠ 当前草稿分辨率较低,不建议开启长镜头:低清尾帧作参考图会导致画面质量与人物一致性明显下降": "⚠ دقة المسودة الحالية منخفضة، لا يُنصح بتفعيل اللقطة الطويلة: استخدام إطار أخير منخفض الدقة كمرجع سيؤدي إلى تدهور ملحوظ في جودة الصورة واتساق الشخصيات",
"Seedance 2.5(Fal 托管;单段 4-30 秒,参考 30 图/10 视频/10 音频,480p/720p/1080p)": "Seedance 2.5 (مستضاف على Fal؛ مقطع واحد 4–30 ث، مراجع 30 صورة/10 فيديو/10 صوت، 480p/720p/1080p)",
