"FLUX Kontext Max(Fal 托管;文生图/多参考图编辑)": "FLUX Kontext Max (مستضاف على Fal؛ نص إلى صورة / تحرير بمراجع متعددة)",
"Qwen Image 3(Fal 托管;中英提示词,参考图 ≤3,支持负面提示词)": "Qwen Image 3 (مستضاف على Fal؛ موجهات صينية/إنجليزية، حتى 3 صور مرجعية، يدعم الموجه السلبي)",
"HunyuanImage 3.0(Fal 托管;仅文生图,支持负面提示词)": "HunyuanImage 3.0 (مستضاف على Fal؛ نص إلى صورة فقط، يدعم الموجه السلبي)",
"Fal 图像生成 API(queue.fal.run 异步队列,托管 Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image 等端点);模型 ID 填家族前缀,无参考图走文生图端点、有参考图自动切 edit 端点,「自定义…」也可填完整端点 ID;尺寸/参考图上限/seed 按模型映射;Key 与视频段 Fal 共用(任一处填写即可),在": "واجهة توليد الصور من Fal (طابور غير متزامن queue.fal.run يستضيف Seedream وNano Banana وGPT Image وFLUX.2 وQwen Image وغيرها)؛ معرّف النموذج هو بادئة العائلة: بلا مراجع تُستخدم نقطة نص-إلى-صورة، ومع المراجع يُختار تلقائيًا نقطة التحرير؛ «مخصص…» يقبل أيضًا معرّف نقطة نهاية كاملًا؛ الحجم / حد المراجع / seed تُطابَق حسب النموذج؛ المفتاح مشترك مع تبويب الفيديو → Fal (يكفي إدخاله في مكان واحد)، ويُنشأ في",
"MiniMax H3 Max(Fal 托管;H3 后训练版,提示遵循更强)": "MiniMax H3 Max (مستضاف على Fal؛ نسخة H3 بعد التدريب الإضافي، التزام أقوى بالموجّه)",
"MiniMax H3 Max Turbo(Fal 托管;速度优先版,仅文生/首尾帧,480P/768P,不支持参考素材)": "MiniMax H3 Max Turbo (مستضاف على Fal؛ نسخة سريعة، نص/الإطار الأول والأخير فقط، 480P/768P، لا يدعم مواد المراجع)",
"Kling 3.0 Pro(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Pro (مستضاف على Fal؛ الإطار الأول/الأخير، 3–15 ث، صوت أصلي، لا يدعم مواد المراجع)",
"Kling 3.0 Standard(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Standard (مستضاف على Fal؛ الإطار الأول/الأخير، 3–15 ث، صوت أصلي، لا يدعم مواد المراجع)",
"Fal 视频生成 API(queue.fal.run 异步队列,托管 Seedance 2.0/2.5、MiniMax H3、Kling 3.0、Wan 3.0 等端点);模型 ID 填家族前缀,按输入自动补 text-to-video / image-to-video / reference-to-video 任务段,「自定义…」也可填完整端点 ID;分辨率/时长/参考素材上限随所选模型(与官方渠道同口径);Key 在": "واجهة توليد الفيديو من Fal (طابور غير متزامن queue.fal.run يستضيف نقاط Seedance 2.0/2.5 وMiniMax H3 وKling 3.0 وWan 3.0 وغيرها)؛ معرّف النموذج هو بادئة العائلة ويُضاف مقطع المهمة text-to-video / image-to-video / reference-to-video تلقائيًا حسب المدخلات، أو اختر «مخصص…» لإدخال معرّف نقطة نهاية كامل؛ حدود الدقة/المدة/المراجع تتبع النموذج المختار (نفس قواعد القنوات الرسمية)؛ أنشئ المفتاح في",
