"人物/场景/风格锚图;每一轮都会连同上一段的尾帧一起作为参考提交,保持人物一致。启动后冻结,停止后可改。": "صور مرجعية للشخصيات/المشهد/الأسلوب؛ تُرسل في كل جولة كمراجع مع آخر إطار من المقطع السابق للحفاظ على اتساق الشخصيات. تُجمَّد بعد البدء ويمكن تعديلها بعد الإيقاف.",
