"例如:一位年轻主播坐在暖光直播间里,面对镜头微笑聊天,偶尔喝一口咖啡,背景霓虹灯牌缓慢闪烁": "مثال: مذيع شاب يجلس في غرفة بث دافئة الإضاءة، يبتسم ويتحدث إلى الكاميرا، يرتشف القهوة أحيانًا، ولافتة نيون تومض ببطء في الخلفية",
