"⚠ {reason}。视频生成模型会拒绝提交,请二选一:① 在下方删除多余/过长的参考视频;② 点「🎛 模型」给本组单独换参考视频上限更高的视频模型(如 Seedance 2.5:≤10 个/总时长 ≤30s,渠道不变)。处理后重出本组。": "⚠ {reason}. سيرفض نموذج الفيديو الإرسال. اختر أحد الخيارين: ① حذف المقاطع المرجعية الزائدة / الطويلة جدًا أدناه؛ ② الضغط على «🎛 النموذج» لمنح هذه المجموعة نموذجًا بحد أعلى للمقاطع المرجعية (مثل Seedance 2.5: ≤10 مقاطع / ≤30 ث إجمالًا، نفس المزوّد). ثم أعد توليد المجموعة.",
"(本组暂无参考视频)": "(لا توجد مقاطع مرجعية في هذه المجموعة)",
"时长 <b>{d}</b>": "المدة <b>{d}</b>",
"时长未知(ffprobe 不可用)": "المدة غير معروفة (ffprobe غير متاح)",
"与 prompt 正文 [Video N] 引用同号": "نفس رقم الإشارة [Video N] في نص الـ prompt",
"🧊 白模": "🧊 Whitebox",
"⏭ 前组尾段": "⏭ ذيل المجموعة السابقة",
"📎 流水线": "📎 خط الإنتاج",
"流水线注入的参考视频(非手动添加);流水线重跑时会按预算重新挂回": "مقطع مرجعي أضافه خط الإنتاج (ليس يدويًا)؛ إعادة تشغيل خط الإنتاج تعيد إرفاقه ضمن الميزانية",
"系统添加": "مضاف من النظام",
"删除这个流水线注入的参考视频(需确认;重出本组生效)": "حذف هذا المقطع المرجعي المضاف من خط الإنتاج (يلزم التأكيد؛ يسري عند إعادة توليد المجموعة)",
"删除这个参考视频(重出本组生效)": "حذف هذا المقطع المرجعي (يسري عند إعادة توليد المجموعة)",
"⚠ 参考视频 [Video {n}] 由流水线注入({kind}),不是手动添加的:\n{ref}\n\n删除后 prompt 正文中的 [Video N] 引用会自动重排,指向该视频的引用与其固定说明段会被移除;流水线重跑同步脚本时会按模型预算重新挂回(要彻底不用请换模型或关闭对应项目开关)。重出本组生效。\n\n确定删除?": "⚠ المقطع المرجعي [Video {n}] أضافه خط الإنتاج ({kind}) وليس يدويًا:\n{ref}\n\nبعد الحذف يُعاد ترقيم إشارات [Video N] في الـ prompt تلقائيًا، وتُزال الإشارات إلى هذا المقطع وفقرته التوضيحية الثابتة. إعادة تشغيل سكربت المزامنة تعيد إرفاقه ضمن ميزانية النموذج (للاستغناء عنه نهائيًا غيّر النموذج أو عطّل إعداد المشروع المعني). يسري عند إعادة توليد المجموعة.\n\nهل تريد الحذف؟",
"确认移除这个参考视频 [Video {n}]?\n{ref}\n(本地上传的文件将一并删除;移除后随本组重出生效)": "حذف المقطع المرجعي [Video {n}]؟\n{ref}\n(سيُحذف الملف المرفوع أيضًا؛ يسري عند إعادة توليد المجموعة)",
"✅ 已删除参考视频": "✅ تم حذف المقطع المرجعي",
"文件超过 45MB(方舟参考视频单文件上限),请先压缩": "حجم الملف يتجاوز 45MB (حد Ark لكل مقطع مرجعي)؛ اضغطه أولًا",
"✅ 已上传并加入参考视频 [Video {n}];重出本组 prompt 时须补写该编号的说明句": "✅ تم الرفع والإضافة كـ [Video {n}]؛ أضف جملة لهذا الرقم عند إعادة توليد prompt المجموعة",
"{n} 个参考视频": "{n} مقاطع مرجعية",
"⚠ {reason}:点「🎬 视频」删除参考视频,或点「🎛 模型」给本组单独换参考视频上限更高的视频模型;处理后重出本组": "⚠ {reason}: اضغط «🎬 فيديو» لحذف مقاطع مرجعية، أو «🎛 النموذج» لمنح هذه المجموعة نموذجًا بحد أعلى؛ ثم أعد توليد المجموعة",
