"➕ 创建全景图": "➕ إنشاء بانوراما",
// 「3D 白模」板块的「创建全景图」(2026-10-05):按白模旋转视角当前的相机位置与朝向出一张,弹窗确认后才创建
"按白模旋转视角当前的摄像机位置(x / y / z)与朝向(yaw)出一张 2:1 全景(只出这一张,其它锚点不动;消耗全景模型出图费用)": "إنشاء بانوراما واحدة 2:1 من موضع الكاميرا الحالي (x / y / z) واتجاهها (yaw) في العرض القابل للدوران للنموذج الأولي (هذه فقط؛ لا تتغير نقاط الارتكاز الأخرى؛ تستهلك رصيد نموذج البانوراما)",
"请先把「3D 白模」切到「旋转视角」,再按当前视角创建全景图": "بدّل «نموذج أولي ثلاثي الأبعاد» إلى «عرض قابل للدوران» أولاً، ثم أنشئ البانوراما من العرض الحالي",
"当前白模摄像机 ({x}, {z}) 在场景地面范围之外(x ±{mx} m、z ±{mz} m 以内才能出全景),请先把视角移到场景内": "كاميرا النموذج الأولي ({x}, {z}) خارج أرضية المشهد (تحتاج البانوراما إلى x ضمن ±{mx} م و z ضمن ±{mz} م). انقل العرض إلى داخل المشهد أولاً",
"当前白模摄像机在地面以下,请先把视角升到地面以上": "كاميرا النموذج الأولي تحت الأرض. ارفع العرض فوق الأرض أولاً",
"将基于当前的白模摄像机位置和视角来创建全景图:\n位置 x {x} · y {y} · z {z} m,朝向 yaw {yaw}°\n光照方案:{scheme}\n\n只出这一张,其它锚点不动;消耗全景模型出图费用。确认创建?": "سيتم إنشاء بانوراما استناداً إلى موضع كاميرا النموذج الأولي الحالي واتجاه العرض:\nالموضع x {x} · y {y} · z {z} م، الاتجاه yaw {yaw}°\nمخطط الإضاءة: {scheme}\n\nتُنشأ هذه فقط؛ لا تتغير نقاط الارتكاز الأخرى؛ تستهلك رصيد نموذج البانوراما. هل تريد الإنشاء؟",
// 稀疏悬空预检(2026-10-05):悬空高视点且白模全景里体块太少的位置,出图前先弹窗确认
"这个位置是悬空高视点(镜头离地约 {height} m),白模全景里地面以上的体块只占 {blocks}%(低于 {limit}%)。\n这样的全景多半会被图像模型出成航拍广角照片、被投影机检拒收,白花一次出图费用;主体在全景里只占很小一块,重投影成分镜背景图也会糊。\n\n建议取消后把位置挪近 / 放低再创建。仍要按这个位置出图?": "هذا الموضع نقطة رؤية معلّقة في الهواء (العدسة على ارتفاع نحو {height} م فوق الأرض)، والكتل الواقعة فوق الأرض لا تغطي سوى {blocks}% من بانوراما النموذج الأولي (أقل من {limit}%).\nعلى الأرجح سيحوّل نموذج الصور بانوراما كهذه إلى صورة جوية واسعة الزاوية يرفضها فحص الإسقاط، فتضيع عملية توليد واحدة؛ كما أن العنصر الرئيسي لا يشغل إلا جزءاً صغيراً من البانوراما، فتخرج خلفيات اللقطات المعاد إسقاطها منها ضبابية.\n\nالأفضل الإلغاء ثم الإنشاء في موضع أقرب / أخفض. هل تريد التوليد في هذا الموضع على أي حال؟",
"服务未重启:创建全景图接口不可用": "لم تتم إعادة تشغيل الخدمة: واجهة إنشاء البانوراما غير متاحة",
"项目「白模」选项已关闭,不能生成全景图": "خيار «النموذج الأبيض» للمشروع مغلق، لا يمكن إنشاء البانوراما",
"该场景还没有白模,不能出全景(先建场景白模)": "لا يوجد نموذج أبيض لهذا المشهد بعد؛ أنشئه أولاً",
"在俯视图上点一个坐标(或直接填 x/z),给该位置出一张 2:1 全景(只出这一张,其它锚点不动;消耗全景模型出图费用)": "انقر نقطة على المنظر العلوي (أو أدخل x/z) لإنشاء بانوراما 2:1 واحدة في ذلك الموضع (هذه فقط؛ المراسي الأخرى لا تتغير؛ يستهلك توليد نموذج البانوراما)",
"正在生成全景图…": "جارٍ إنشاء البانوراما…",
"该场景还没有全景图;点「创建全景图」在俯视图上选一个位置出图,或由分镜背景图链自动规划锚点": "لا توجد بانوراما لهذا المشهد بعد. انقر «إنشاء بانوراما» لاختيار موضع على المنظر العلوي، أو دع سلسلة لوحات اللقطات تخطط المراسي تلقائياً",
