"请先在俯视图上点一个位置,或填写 x/z 坐标": "انقر أولاً موضعاً على المنظر العلوي أو أدخل x/z",
"相机脚下平面的海拔,0 = 地面;相机高度 = y + 眼高。点位后按该处高度自动填,可再改": "ارتفاع السطح الذي تقف عليه الكاميرا؛ 0 = الأرض. ارتفاع الكاميرا = y + مستوى العين. يُملأ تلقائياً من الارتفاع عند الموضع المختار؛ قابل للتعديل",
