"拖动旋转改朝向(yaw);靠近 0/90/180/270° 自动吸附,按住 Shift 不吸附": "اسحب لتدوير الاتجاه (yaw)؛ يلتصق قرب 0/90/180/270°، اضغط Shift لتعطيل الالتصاق",
"y(脚下平面海拔)须为不小于 0 的数字": "يجب أن تكون y (ارتفاع السطح) رقماً لا يقل عن 0",
