"在俯视图上点一下选择全景中心(坐标为白模米制,原点在场景中心)": "انقر المنظر العلوي لاختيار مركز البانوراما (أمتار النموذج الأبيض، الأصل في مركز المشهد)",
"滚轮缩放,拖动平移,双击复位": "مرّر للتكبير، اسحب للتحريك، انقر مرتين لإعادة الضبط",
"该场景没有俯视图,请直接填写 x/z 坐标(白模米制,原点在场景中心)": "لا يوجد منظر علوي لهذا المشهد؛ أدخل x/z مباشرة (أمتار النموذج الأبيض، الأصل في مركز المشهد)",
"全景图生成完成": "اكتمل إنشاء البانوراما",
"全景图生成失败:": "فشل إنشاء البانوراما: ",
