"全景锚点 {marker}(场景 {scene};索引 {file};锚点 {anchors};改动后重出:python code/render_scene_panos.py --project {proj} --scene {scene} --anchor x,z --force,再 python code/render_shot_plates.py --project {proj} --ep <ep> --repano)": "مراسي البانوراما {marker} (المشهد {scene}؛ الفهرس {file}؛ المراسي {anchors}؛ بعد التعديل أعد التوليد: python code/render_scene_panos.py --project {proj} --scene {scene} --anchor x,z --force ثم python code/render_shot_plates.py --project {proj} --ep <ep> --repano)",
"当前全景图像模型 {model}({provider})不支持 2:1 全景,全景图与分镜背景图已暂停:请在本页顶部「🌐 全景模型」或控制台「🎨 生成模型」切换后重跑 code/render_shot_plates.py": "نموذج صور البانوراما الحالي {model} ({provider}) لا يدعم بانوراما 2:1؛ تم إيقاف البانوراما وخلفيات اللقطات. بدّله أعلى هذه الصفحة في «🌐 نموذج البانوراما» أو في وحدة التحكم «🎨 نماذج التوليد» ثم أعد تشغيل code/render_shot_plates.py",
"中心 ({x}, {z}) m · 高 {h} m · yaw {yaw}°": "المركز ({x}, {z}) م · الارتفاع {h} م · yaw {yaw}°",
