"语音输入:开启后控制台与预览页「修改」浮窗的输入框出现麦克风按钮,录音由本机 faster-whisper 转成文字,音频不出本机": "الإدخال الصوتي: عند التفعيل يظهر زر ميكروفون في مربع إدخال وحدة التحكم ونافذة «تعديل» في صفحات المعاينة؛ تُحوَّل التسجيلات إلى نص محليًا عبر faster-whisper ولا يغادر الصوت هذا الجهاز",
"🎤 语音输入": "🎤 الإدخال الصوتي",
