"开启后控制台输入框与预览页「修改」浮窗的右侧出现麦克风按钮:点一下开始录音、再点一下结束,录音由本机 faster-whisper 模型转成文字插到光标处(最长 60 秒,音频不出本机,不需要任何 API Key)。识别语言跟随界面语言。模型首次使用需先下载,越大的模型越准但越慢:small 起步够用,Apple 芯片可选 medium 或 large-v3-turbo。": "عند التفعيل يظهر زر ميكروفون على يمين مربع إدخال وحدة التحكم ونافذة «تعديل» في صفحات المعاينة: انقر مرة لبدء التسجيل ومرة أخرى للإيقاف؛ يُحوَّل التسجيل إلى نص بنموذج faster-whisper المحلي ويُدرج عند المؤشر (60 ثانية كحد أقصى، الصوت لا يغادر الجهاز، ولا حاجة لمفتاح API). لغة التعرف تتبع لغة الواجهة. يجب تنزيل النموذج قبل أول استخدام؛ النماذج الأكبر أدق لكنها أبطأ: small كافٍ للبداية، وعلى شرائح Apple يمكن اختيار medium أو large-v3-turbo.",
