"模型未下载:点「下载模型」拉取到本机 data/models/faster-whisper/": "لم يُنزَّل النموذج: انقر «تنزيل النموذج» لجلبه إلى data/models/faster-whisper/ على هذا الجهاز",
"这里选中的识别模型也是本机所有语音识别统一使用的模型:素材库对白识别、音频转文字(数字人等插件流程)、花字与混剪的语音对齐都用它,与上方开关无关(开关只控制输入框的麦克风按钮)。这些流程用到尚未下载的模型时会自动下载。": "النموذج المحدد هنا هو نفسه المستخدم في كل عمليات التعرف على الكلام محليًا: التعرف على الحوار في مكتبة المواد، وتحويل الصوت إلى نص (الإنسان الرقمي وغيره من مسارات الإضافات)، ومحاذاة الكلام للعناوين المزخرفة والمونتاج المجمّع — بصرف النظر عن المفتاح أعلاه (فهو يتحكم فقط في زر الميكروفون في حقول الإدخال). إذا احتاج أحد هذه المسارات إلى نموذج لم يُنزَّل بعد فسيُنزَّل تلقائيًا.",
