"用本机人声分离模型把对白 / 人声从原生声轨里去掉,保留音效、环境声和配乐;画面不重编码。人声保留 -60 = 完全去掉,调高 = 只压低。首次使用自动下载模型(约 64 MB);提交后要重跑混音才进成片": "يستخدم نموذجًا محليًا لفصل الصوت البشري لإزالة الحوار / الأصوات البشرية من المسار الصوتي الأصلي مع إبقاء المؤثرات والصوت المحيط والموسيقى؛ لا يُعاد ترميز الصورة. إبقاء الصوت البشري -60 = إزالة كاملة، والقيمة الأعلى = تخفيض فقط. يُنزَّل النموذج (نحو 64 MB) عند أول استخدام؛ بعد الإرسال يجب إعادة المزج حتى يصل التغيير إلى النسخة النهائية",
"只留人声:用本机人声分离模型把音效、环境声和配乐从原生声轨里去掉;画面不重编码。环境声保留 -60 = 完全去掉,调高 = 只压低。首次使用自动下载模型(约 64 MB);提交后要重跑混音才进成片": "إبقاء الأصوات البشرية فقط: يستخدم نموذجًا محليًا لفصل الصوت البشري لإزالة المؤثرات والصوت المحيط والموسيقى من المسار الصوتي الأصلي؛ لا يُعاد ترميز الصورة. إبقاء الصوت المحيط -60 = إزالة كاملة، والقيمة الأعلى = تخفيض فقط. يُنزَّل النموذج (نحو 64 MB) عند أول استخدام؛ بعد الإرسال يجب إعادة المزج حتى يصل التغيير إلى النسخة النهائية",
"本机模型 · 约为片长的一半 · ¥0(首次使用下载模型约 64 MB)": "نموذج محلي · نحو نصف مدة المقطع · ¥0 (أول استخدام ينزّل نموذجًا بحجم نحو 64 MB)",
