"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片时外挂声轨/字幕按时间映射表自动同步)": "يحذف المقاطع المحددة ويصل الباقي بالترتيب في نسخة جديدة من هذه المجموعة (تقصر المدة؛ عند الإخراج النهائي تُعاد مزامنة الصوت الخارجي والترجمة عبر خريطة الزمن)",
"控制切换节奏:在当前时刻插入「前一帧定格 + 黑场」生成本组新版本;或放在本组开头 / 结尾的组边界,写成组间转场调整(提交即回写 shot_list,出成片时插帧)。成片按插入量变长,外挂声轨与字幕按同一张时间映射表自动平移;黑场声音可延续前段、淡出或静音": "التحكم بالإيقاع: أدرج «تجميد الإطار السابق + أسود» عند موضع التشغيل لإنشاء نسخة جديدة، أو ضعه على حد بداية / نهاية هذه المجموعة كتعديل انتقال بين المجموعات (الإرسال يكتبه في shot_list وتُدرج الإطارات عند الإخراج النهائي). تطول الحلقة بمقدار الإدراج؛ ينزاح الصوت الخارجي والترجمة بنفس خريطة الزمن؛ ويمكن للصوت تحت الأسود أن يستمر أو يخفت أو يصمت",
"分镜剪辑,四个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 插黑 / 定格——在当前时刻或组边界插入定格帧 + 黑场控制切换节奏;④ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "تحرير اللقطات، أربع وحدات: ① حذف — إزالة المقاطع المحددة ويصبح الباقي نسخة جديدة؛ ② استبدال — استبدال المقاطع المقصوصة بنفس المقاطع من نسخة أخرى؛ ③ أسود / تجميد — إدراج إطار مجمّد + أسود عند موضع التشغيل أو على حد المجموعة للتحكم بالإيقاع؛ ④ إرسال إلى المونتير — إرسال تعليمة لوكيل المونتاج وتسجيل الناتج كنسخة جديدة",
"+{s}s → {r}s": "+{s}s → {r}s",
"{a} → {b} 的组边界:前组尾定格 / 黑场后进入本组(写入本组的组间转场调整)": "الحد {a} → {b}: تجميد آخر إطار من المجموعة السابقة / أسود ثم الدخول إلى هذه المجموعة (يُكتب في تعديل انتقال هذه المجموعة)",
"{a} → {b} 的组边界:本组尾定格 / 黑场后进入下组(写入下组的组间转场调整)": "الحد {a} → {b}: تجميد آخر إطار من هذه المجموعة / أسود ثم الدخول إلى المجموعة التالية (يُكتب في تعديل انتقال المجموعة التالية)",
"以 v{a} 为基准,在 {t} 处插入 {p},生成 {g} 的新版本?": "اعتماد v{a} أساسًا وإدراج {p} عند {t} وإنشاء نسخة جديدة من {g}؟",
