"在 A 的当前播放时刻插入,生成本组新版本": "الإدراج عند موضع التشغيل الحالي في A وإنشاء نسخة جديدة من هذه المجموعة",
"基准 v{v} 已含 {n} 处时长编辑,新插入将叠加": "الأساس v{v} يحوي بالفعل {n} تعديل مدة؛ سيُضاف الإدراج الجديد فوقه",
