"穿黑(前组淡出 → 黑场 → 本组淡入)": "عبر الأسود (السابقة تخفت → أسود → هذه المجموعة تدخل بتدرج)",
"立即提交": "إرسال الآن",
"纯黑帧数,24fps;控节奏常用 6–24 帧,超过 1 秒观众会当成故障": "عدد إطارات الأسود الخالص، 24 إطارًا/ث؛ المعتاد للإيقاع 6–24 إطارًا، وأكثر من ثانية يبدو عطلًا",
"节奏:{a} → {b} 边界{p}({t})": "الإيقاع: الحد {a} → {b} {p} ({t})",
"草稿在右侧「包装 › 组间转场(入)」,点「提交」生效": "المسودة على اليمين ضمن «التغليف › انتقال المجموعة (دخول)»؛ اضغط «إرسال» لتفعيلها",
"超过 1 秒的黑场易被当成故障": "الأسود لأكثر من ثانية يبدو عطلًا غالبًا",
"边界 {a} → {b} 现状:{s}": "الحد {a} → {b} حاليًا: {s}",
