"黑场声音": "الصوت تحت الأسود",
"黑屏": "أسود",
"叙事块 ": "الكتلة السردية ",
"工位自动开的调整:": "تعديل فتحته المحطة تلقائيًا: ",
"提交这 {n} 条调整,当前指针挪到 v{v}(出成片用它)": "إرسال هذه التعديلات ({n}) ونقل المؤشر الحالي إلى v{v} (يُستخدم للنسخة النهائية)",
"柔化(高频软化)": "تنعيم (تليين الترددات العالية)",
"半径(1080p 基准 px)": "نصف القطر (بكسل عند 1080p)",
"高斯模糊与原片按强度混合,压掉高频细节而不糊轮廓(回忆/梦境段的柔焦感);半径随画面高度等比缩放": "يمزج تمويهًا غاوسيًا مع الأصل حسب الشدة، فيزيل التفاصيل الدقيقة دون تلطيخ الحواف (إحساس التركيز الناعم لمقاطع الاسترجاع / الأحلام)؛ يتناسب نصف القطر مع ارتفاع الصورة",
"全部集": "كل الحلقات",
"按集过滤:只显示该集出现的资产": "تصفية حسب الحلقة: عرض الأصول التي تظهر فيها فقط",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度、白模自检、Debug 模式": "إعدادات الوكلاء المتقدمة: حد التزامن لوكلاء fan-out، مهلات التشغيل / انعدام المخرجات، حصة ذاكرة المحادثة عبر الأدوار، الحد الأقصى لإعادة التشغيل التلقائية، مدة انتظار تأكيد الإعادة، عمق التفكير، الفحص الذاتي للنموذج الأبيض، وضع التصحيح",
"白模自检": "الفحص الذاتي للنموذج الأبيض",
"显示 SOUL.md 等开发者入口": "إظهار مداخل المطورين مثل SOUL.md",
"白模调度编译后出静帧自检取景": "إخراج لقطات ثابتة بعد تجميع النموذج الأبيض للتحقق الذاتي من التأطير",
"默认勾选:白模调度 Agent 每次新建或修改分镜白模、编译通过后,用宿主命令 render_whitebox.py --stills 对本单改动过的组做无头渲染——每镜取首/中/尾等时刻的摄影机视角加一张空间视角,拼成每组一张联系表(项目 directing 下该集的 whitebox/stills 目录),Agent 读图核对主体是否在画内、有无被墙或道具遮挡、正面/背影与调度是否一致、景别是否相符,有问题先自行修正或开待决项,再交你在预览页审看签字。渲染全在本机完成,不调用任何生成模型、不产生费用,也不导出 camera.mp4(导出仍须 H3W 签字);每组约多花十几秒与一次读图的 token。取消勾选则只做数值自检与宿主机检,不出静帧。全局设置,通过运行提示词注入白模调度 Agent,保存后对后续启动的工单生效。": "محدد افتراضيًا: في كل مرة ينشئ فيها وكيل إخراج النموذج الأبيض نموذجًا أبيض للقصة المصورة أو يعدّله وتنجح عملية التجميع، يشغّل أمر المضيف render_whitebox.py --stills على المجموعات التي تغيّرت في أمر العمل هذا. يتم التصيير بلا واجهة: لكل لقطة مناظر الكاميرا عند البداية / المنتصف / النهاية (ولحظات رئيسية أخرى) مع منظر مكاني واحد، تُجمع في ورقة تماس واحدة لكل مجموعة (في مجلد whitebox/stills للحلقة ضمن directing في المشروع). يقرأ الوكيل الورقة للتحقق من أن الموضوع داخل الإطار، وأنه غير محجوب بجدران أو أغراض، وأن الواجهة / الظهر يطابقان الإخراج، وأن حجم اللقطة مناسب؛ ويصلح المشكلات بنفسه أو يفتح بندًا معلقًا قبل تسليمه إليك للمراجعة والتوقيع في صفحة المعاينة. التصيير محلي بالكامل: لا يُستدعى أي نموذج توليدي ولا توجد تكلفة ولا يُصدَّر camera.mp4 (ما زال التصدير يتطلب توقيع H3W)؛ تكلّف كل مجموعة نحو عشر ثوانٍ إضافية ورموز قراءة صورة واحدة. عند إلغاء التحديد تُجرى الفحوص الرقمية وفحوص المضيف فقط دون لقطات ثابتة. إعداد عام يُحقن في وكيل إخراج النموذج الأبيض عبر موجّه التشغيل؛ يسري على أوامر العمل التي تبدأ بعد الحفظ.",
"本组尚未白模调度，当前没有可审看的白模。": "لم تخضع هذه المجموعة بعد لإخراج النموذج الأبيض؛ لا يوجد نموذج أبيض للمراجعة حاليًا.",
"白模调度 Agent 完成本集工单后这里会显示正式白模；在此之前无需对白模提修改意见。": "سيظهر النموذج الأبيض الرسمي هنا بعد أن يُنهي وكيل إخراج النموذج الأبيض أمر عمل هذه الحلقة؛ ولا حاجة قبل ذلك لإرسال ملاحظات تعديل على النموذج الأبيض.",
"系统按分镜与动线自动推断的粗略白模，机位、走位、朝向多为估计值，不是白模调度的交付物": "نموذج أبيض تقريبي استنتجه النظام تلقائيًا من القصة المصورة وخطوط الحركة؛ مواضع الكاميرا والتحركات والاتجاهات تقديرية في معظمها وليست من مخرجات إخراج النموذج الأبيض",
"查看自动推断草稿（仅供参考，不接受修改）": "عرض المسودة المستنتجة تلقائيًا (للاطلاع فقط، لا تُقبل التعديلات)",
"自动推断草稿": "مسودة مستنتجة تلقائيًا",
"自动推断草稿：本组未经白模调度，以下画面由系统按分镜与动线粗略推断，仅供参考；修改入口在白模调度完成后开放。": "مسودة مستنتجة تلقائيًا: لم تخضع هذه المجموعة لإخراج النموذج الأبيض. الصورة أدناه مستنتجة تقريبيًا من القصة المصورة وخطوط الحركة وهي للاطلاع فقط؛ تُفتح منافذ التعديل بعد اكتمال إخراج النموذج الأبيض.",
"本组尚未白模调度,当前是系统自动推断的草稿,只能查看;白模调度完成后再提修改": "لم تخضع هذه المجموعة بعد لإخراج النموذج الأبيض؛ المعروض مسودة مستنتجة تلقائيًا وللعرض فقط. أرسل التعديلات بعد اكتمال إخراج النموذج الأبيض",
