"右下角弹出消息窗,把这张缺陷单发给总制片处理": "يفتح نافذة رسالة أسفل اليمين لإرسال بطاقة العيب هذه إلى المنتج العام",
"全部分集": "كل الحلقات",
"只看未关闭": "غير المغلقة فقط",
"未关闭 {n} 条": "{n} غير مغلقة",
"按分集过滤": "تصفية حسب الحلقة",
