"勾选:在手绘稿基础上由 AI 按对应风格重绘;不勾选:直接使用手绘原图": "محدد: يعيد الذكاء الاصطناعي رسم مسودتك بالأسلوب المناسب؛ غير محدد: يُستخدم الرسم الأصلي كما هو",
"画一张分镜草图,提交后 AI 按分镜草图风格重绘,作为该镜草图": "ارسم مسودة لوحة قصة؛ بعد الإرسال يعيد الذكاء الاصطناعي رسمها بأسلوب مسودات لوحة القصة لتصبح مسودة هذه اللقطة",
"可选:补充说明(构图/人物/动作,AI 重绘时参考)": "اختياري: ملاحظات إضافية (التكوين / الشخصيات / الحركة) يستعين بها الذكاء الاصطناعي عند إعادة الرسم",
"手绘原图将直接加入本组参考图(不经 AI 加工)": "سيُضاف الرسم الأصلي مباشرةً إلى صور مرجع هذه المجموعة (دون معالجة بالذكاء الاصطناعي)",
"可选:这张图表达什么": "اختياري: ما الذي يعبّر عنه هذا الرسم",
"✅ 已提交 {f},AI 正在按分镜草图风格重绘,请回故事板页查看进度": "✅ تم إرسال {f}؛ يعيد الذكاء الاصطناعي رسمه بأسلوب مسودات لوحة القصة — تابع التقدم في صفحة لوحة القصة",
"✅ 已提交 {f},手绘原图已直接加入本组参考图,请回桌面端查看": "✅ تم إرسال {f}؛ أُضيف الرسم الأصلي إلى صور مرجع هذه المجموعة — اطّلع عليه على سطح المكتب",
"手机扫码手绘构图线稿;勾选「AI 加工」(默认)结合已有参考图按项目风格生成最终参考图,不勾选则手绘原图直接加入本组": "امسح الرمز بهاتفك وارسم مسودة تكوين؛ عند تحديد «معالجة بالذكاء الاصطناعي» (افتراضي) تُنشأ صورة مرجعية نهائية من المسودة والمراجع الموجودة وأسلوب المشروع؛ وعند إلغاء التحديد يُضاف الرسم الأصلي مباشرةً إلى المجموعة",
"手机扫码打开画布(同一局域网);画构图线稿并配文字说明,提交后结合本组已有参考图与项目风格生成最终参考图,自动加入本组;画布页取消勾选「AI 加工」则手绘原图直接加入本组": "امسح رمز QR بهاتفك لفتح لوحة الرسم (الشبكة المحلية نفسها)؛ ارسم مسودة تكوين وأضف ملاحظة نصية — بعد الإرسال تُنشأ صورة مرجعية نهائية من المسودة ومراجع المجموعة الموجودة وأسلوب المشروع وتُضاف تلقائيًا؛ ألغِ تحديد «معالجة بالذكاء الاصطناعي» في صفحة الرسم لإضافة الرسم الأصلي مباشرةً",
"✅ 手绘原图已加入本组参考图": "✅ أُضيف الرسم الأصلي إلى صور مرجع هذه المجموعة",
"手机扫码打开画布(同一局域网);画好提交后由 AI 按分镜草图风格重绘作为该分镜的草图;画布页取消勾选「AI 加工」则手绘原图直接作为草图": "امسح رمز QR بهاتفك (الشبكة المحلية نفسها) لفتح لوحة الرسم؛ بعد الإرسال يعيد الذكاء الاصطناعي رسمه بأسلوب مسودات لوحة القصة كمسودة لهذه اللقطة؛ ألغِ تحديد «معالجة بالذكاء الاصطناعي» في صفحة الرسم لاستخدام الرسم الأصلي مباشرةً",
"手机扫码画一张草图;默认由 AI 按分镜草图风格重绘,画布页取消勾选「AI 加工」则原图直接作为这一镜的草图": "امسح الرمز بهاتفك وارسم مسودة؛ افتراضيًا يعيد الذكاء الاصطناعي رسمها بأسلوب مسودات لوحة القصة — ألغِ تحديد «معالجة بالذكاء الاصطناعي» في صفحة الرسم لاستخدام الأصل كمسودة لهذه اللقطة",
"手绘稿 AI 加工": "رسم يدوي معالج بالذكاء الاصطناعي",
"✅ 已收到手绘稿,AI 正在按分镜草图风格重绘…": "✅ تم استلام الرسم؛ يعيد الذكاء الاصطناعي رسمه بأسلوب مسودات لوحة القصة…",
"MiniMax H3 Max Lip Sync(Fal 托管;对口型:1 张人物图 + 1 段 5–14.8 秒音频,无提示词,成片时长随音频,480P/768P/1080P/2K)": "MiniMax H3 Max Lip Sync (مستضاف على Fal؛ مزامنة الشفاه: صورة شخصية واحدة + مقطع صوتي 5–14.8 ثانية، بلا موجّه، المدة تتبع الصوت، 480P/768P/1080P/2K)",
"MiniMax H3 Max Lip Sync:每段都用第 1 张参考图作人物图(画面不漂,但段与段之间会跳);画幅随图片": "MiniMax H3 Max Lip Sync: كل مقطع يستخدم المرجع رقم 1 كصورة للشخصية (بلا انحراف، لكن مع قفزات بين المقاطع)؛ نسبة الأبعاد تتبع الصورة",
"MiniMax H3 Max Lip Sync:首轮用第 1 张参考图作人物图,之后每轮用上一段尾帧(衔接模式选「不衔接」则每段都用第 1 张参考图);画幅随图片": "MiniMax H3 Max Lip Sync: الجولة الأولى تستخدم المرجع رقم 1 كصورة للشخصية، وما بعدها يستخدم الإطار الأخير من المقطع السابق (مع «بلا ربط» يُستخدم المرجع رقم 1 دائمًا)؛ نسبة الأبعاد تتبع الصورة",
"对口型模型需要至少 1 张参考图(第 1 张作为人物图)": "نموذج مزامنة الشفاه يحتاج إلى صورة مرجعية واحدة على الأقل (الأولى هي صورة الشخصية)",
"💬 台词": "💬 النص المنطوق",
"人物要说的话;按句分段,逐段语音合成后驱动口型": "ما تقوله الشخصية؛ يُقسَّم حسب الجمل، ويُحوَّل كل مقطع إلى كلام ثم يحرّك الشفاه",
"例如:大家好,欢迎来到我的直播间!今天想和大家聊一聊最近在看的一本书。": "مثال: مرحبًا بالجميع، أهلًا بكم في بثّي! اليوم أودّ أن أحدثكم عن كتاب أقرؤه حاليًا.",
"语音用「生成模型」页当前的 TTS 配置与默认音色合成({tts})。台词念完不会停播,会等你更新台词:在原文后面追加的部分接着念,整段改写则从头念新台词。": "يُولَّد الكلام بإعدادات TTS الحالية والصوت الافتراضي من صفحة «نماذج التوليد» ({tts}). لا يتوقف البث عند انتهاء النص بل ينتظر تحديثًا: ما يُضاف بعد النص الأصلي يُنطق تاليًا، أما النص المعاد كتابته فيبدأ من أوله.",
"对口型:台词按句打包成每段约该秒数({lo}–{hi} 秒)的小段;每段成片时长 = 该段语音时长(不足 5 秒补静音)": "مزامنة الشفاه: يُجمَّع النص حسب الجمل في مقاطع بهذه المدة تقريبًا ({lo}–{hi} ثانية)؛ مدة كل مقطع فيديو = مدة كلامه (يُكمَّل بالصمت إن قلّ عن 5 ثوانٍ)",
