// 背景图模式(2026-09-22):输出设置「背景图模式」+ 场景预览页分镜背景图板块按场景选择(全景图 / 世界模型)
"背景图模式": "وضع لوحة الخلفية",
"白模开启时分镜背景图的参考来源(全局设置,场景预览页可按场景覆盖)。两种模式都先为每个场景以俯视图为参考一次生成一张 3×3 宫格(同一站位朝八个方向各一格,外加一格仰拍;站位和机高按本集机位自动确定),拆成 9 张背景图入库,每镜按白模机位自动选最合适的一格。区别在选不到合适格子(朝向/俯仰/距离/机高超限)时:九宫格自动补图 = 自动按本镜机位补出一张(每张计一次出图费用);九宫格手动补图 = 不自动出图,由你在场景预览页的全景图或世界模型视窗里用「💾 背景图」手工截取。": "مصدر مرجع خلفيات اللقطة عند تفعيل النموذج الأبيض (إعداد عام؛ يمكن تجاوزه لكل مشهد من صفحة معاينة المشاهد). يبدأ الوضعان بإنشاء شبكة 3×3 واحدة لكل مشهد اعتمادًا على المخطط العلوي (نقطة وقوف واحدة تنظر في ثمانية اتجاهات، مع خانة إضافية مائلة للأعلى؛ تُحدَّد نقطة الوقوف وارتفاع الكاميرا تلقائيًا من كاميرات هذه الحلقة)، ثم تُقسَّم إلى 9 خلفيات في المكتبة، ويُختار لكل لقطة تلقائيًا الخانة الأنسب لكاميرا النموذج الأبيض. يختلفان عندما لا توجد خانة مناسبة (الاتجاه / الميل / المسافة / ارتفاع الكاميرا خارج الحدود): شبكة 3×3 مع إكمال تلقائي تُنشئ خلفية إضافية بكاميرا تلك اللقطة (تُحتسب كل واحدة كعملية توليد صورة)؛ شبكة 3×3 مع إكمال يدوي لا تُنشئ شيئًا — تلتقط الخلفية بنفسك بزر «💾 لوحة خلفية» في عارض البانوراما أو نموذج العالم في صفحة معاينة المشاهد.",
"本场景分镜背景图的参考来源;默认跟随项目输出设置「背景图模式」,可单独覆盖": "مصدر مرجع لوحات لقطات هذا المشهد؛ يتبع افتراضيًا إعداد إخراج المشروع «وضع لوحة الخلفية» ويمكن تجاوزه هنا",
"跟随全局({m})": "اتباع الإعداد العام ({m})",
"本场景背景图模式为「世界模型」,但尚未生成世界模型:出图链会停下(退出码 4),请先在上方「🌍 世界模型」板块生成": "وضع خلفية هذا المشهد هو «نموذج العالم» لكن لم يُنشأ نموذج عالم بعد: ستتوقف سلسلة اللوحات (رمز الخروج 4). أنشئه أولًا في لوحة «🌍 نموذج العالم» أعلاه",
"前往世界模型": "الانتقال إلى نموذج العالم",
"世界模型(全景 {a})": "نموذج العالم (بانوراما {a})",
"(暂无分镜背景图;白模签字 H3W 并导出后由分镜背景图链生成)": "(لا توجد لوحات خلفية بعد؛ تنشئها سلسلة اللوحات بعد اعتماد النموذج الأبيض في H3W وتصديره)",
"生效 {m}": "ساري {m}",
