"正反两张都出": "الأمامية والعكسية معًا",
"白模关闭时的场景一致性方案:每场景一张正向图(门口往内看),分镜看回望方向时再补一张反向图;平面动画/单面布景选「只出正向」": "أسلوب اتساق المشهد عند إيقاف الوايت بوكس: صورة أمامية واحدة لكل مشهد (النظر إلى الداخل من الباب)، بالإضافة إلى صورة عكسية عندما تنظر لقطة في الاتجاه المعاكس؛ للرسوم المسطحة / الديكورات أحادية الجانب اختر \"الأمامية فقط\"",
"白模已开启:场景一致性由白模视频 + 分镜背景图承担,本项不生效": "الوايت بوكس مفعّل: اتساق المشهد تتولاه فيديوهات الوايت بوكس + خلفيات اللقطات، وهذا الخيار بلا تأثير",
"走「场景图(正向/反向)」流程,不建白模": "استخدام مسار \"صور المشهد (أمامية/عكسية)\" بدون وايت بوكس",
