"旧版主图尚未登记站位/画内清单,先回派环境概念工位补登记再改模式": "الصورة الرئيسية القديمة لم يُسجَّل لها موضع الوقوف / قائمة العناصر داخل الإطار؛ أعد إسناد محطة مفهوم البيئة للتسجيل أولًا ثم غيّر الوضع",
