"反向图未出:分镜定稿后由 p6-scene-plates 补出(code/render_scene_plates.py)": "لم تُنشأ الصورة العكسية بعد: تُنتجها p6-scene-plates بعد اعتماد قائمة اللقطات (code/render_scene_plates.py)",
"本场景不需要反向图": "هذا المشهد لا يحتاج صورة عكسية",
"过期:正向图已重出,需重出反向图": "قديمة: أُعيد إنشاء الصورة الأمامية، ويلزم إعادة إنشاء العكسية",
