"分镜草案没写 narration_ref、镜头表也还没定挂点,宿主按旁白稿锚点引文推定到镜;签字前请核对": "مسودة اللقطات لا تحتوي narration_ref، وقائمة اللقطات لم تحدد المراسي بعد؛ استنتج المضيف اللقطة من اقتباس المرساة في مسودة التعليق الصوتي. يُرجى التحقق قبل التوقيع",
"旁白(正文·估时;灰标 = 宿主推定的挂点)": "التعليق الصوتي (النص · مدة تقديرية؛ الوسم الرمادي = مرساة استنتجها المضيف)",
