"把当前指针挪到 v{v}(出成片用它)": "نقل المؤشر الحالي إلى v{v} (يُستخدم في النسخة النهائية)",
"分镜剪辑,三个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "مونتاج اللقطات، ثلاث وحدات: ① حذف مقطع — تُحذف المقاطع المحددة مباشرة ويُبنى إصدار جديد مما تبقّى؛ ② استبدال مقطع — تُستبدل المقاطع المقطوعة بالمقاطع نفسها من إصدار آخر لهذه المجموعة؛ ③ إرسال إلى المونتير — اكتب تعليمة وأرسلها إلى محطة المونتير، ويُسجَّل ناتجها كإصدار جديد",
"删段": "حذف مقطع",
"换段": "استبدال مقطع",
"派单剪辑师": "إرسال إلى المونتير",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片前需同步时间线)": "تُحذف المقاطع المحددة مباشرة، ويُوصل ما تبقّى بترتيبه الأصلي في إصدار جديد لهذه المجموعة (تقصر المدة؛ زامن الخط الزمني قبل إخراج النسخة النهائية)",
"导入本组另一版本作替换源,A 上标出的时间段换成替换源同一时间段的画面,其余保留,拼成新版本(时长不变)": "استورد إصدارًا آخر لهذه المجموعة كمصدر استبدال: تُستبدل المقاطع المحددة على A بالصورة من المقاطع نفسها في المصدر، ويبقى الباقي كما هو، ويُبنى إصدار جديد (المدة لا تتغير)",
"用一句话把剪辑要求发给剪辑师工位(10-editing/edit);可附上标好的时间段供指令引用,剪辑师产物会登记为本组新版本": "أرسل طلب المونتاج في جملة واحدة إلى محطة المونتير (10-editing/edit)؛ يمكن إرفاق المقاطع المحددة لتشير إليها التعليمة، ويُسجَّل ناتج المونتير كإصدار جديد لهذه المجموعة",
"删 {n} 段 · -{s}s → 剩 {r}s": "حذف {n} مقطع · -{s}s → يتبقى {r}s",
"要删除的时间段(A 的时间线)": "المقاطع المراد حذفها (على الخط الزمني لـ A)",
"时间段(可选,随指令一起发给剪辑师供引用)": "المقاطع (اختياري، تُرسل مع التعليمة ليشير إليها المونتير)",
"没有时间段也能派单;要让剪辑师精确到秒,先在走带条上「标记时间段」": "يمكن الإرسال بلا مقاطع؛ ولتحديد الثواني بدقة للمونتير، استخدم «تحديد مقطع» على شريط التمرير أولًا",
"还没有要删的段:播放 A 找到要删掉的部分,点「标记时间段」设起点、再点一次设终点,即加入列表;可标多段": "لا توجد مقاطع للحذف بعد: شغّل A لتجد الجزء المراد حذفه، وانقر «تحديد مقطع» لنقطة البداية ثم انقر مرة أخرى لنقطة النهاية فيُضاف إلى القائمة؛ ويمكن تحديد عدة مقاطع",
"给剪辑师的指令,例如:第 1 段太拖,砍到 1.5 秒;结尾定格 0.5 秒后再切": "تعليمة للمونتير، مثال: المقطع 1 بطيء، اختصره إلى 1.5 ثانية؛ جمّد الإطار الأخير 0.5 ثانية قبل القطع",
