"未检测到占位符,将按工作流结构自动绑定可识别输入": "لم تُكتشف عناصر نائبة؛ ستُربط المدخلات المعروفة تلقائيًا وفق بنية سير العمل",
"标记剧本关键点": "تحديد النقاط الرئيسية في السيناريو",
"关键情节": "حدث رئيسي",
