"切黑须停留 >0 秒(否则等于停在末帧)": "القطع إلى الأسود يحتاج تثبيتًا > 0 ث (وإلا فهو مجرد توقف عند آخر إطار)",
"正片结尾的收束:最后一组尾部淡出到黑/白后停留,或直接切黑(突然黑屏,悬念感;声音默认同刻切断);外挂声轨同刻淡出/切断,片尾包装接在停留之后。出成片时由 render_transitions 落地;某一集要不同处理可在分镜预览页过场汇总条单独设。": "كيف تنتهي الحلقة: تتلاشى المجموعة الأخيرة إلى الأسود/الأبيض ثم تثبت، أو تقطع مباشرة إلى الأسود (إظلام مفاجئ للتشويق؛ ينقطع الصوت في اللحظة نفسها افتراضيًا)؛ يتلاشى/ينقطع مسار الصوت الخارجي في اللحظة نفسها وتأتي الخاتمة بعد التثبيت. يطبّقه render_transitions عند الإخراج النهائي؛ يمكن تجاوزه لحلقة بعينها من شريط ملخص الانتقالات في صفحة القصة المصورة.",
"正片结尾的收束:最后一组尾部淡出/切黑后停留,外挂声轨同刻淡出或切断;片尾包装接在停留之后": "كيف تنتهي الحلقة: تتلاشى/تقطع المجموعة الأخيرة إلى الأسود ثم تثبت؛ يتلاشى الصوت الخارجي أو ينقطع في اللحظة نفسها؛ تأتي الخاتمة بعد التثبيت",
"本集集尾收束(集级覆盖,项目默认在「视频节奏」设置);改后出成片时落地,已有成片须重跑转场": "إغلاق هذه الحلقة (تجاوز على مستوى الحلقة؛ الإعداد الافتراضي للمشروع في «إيقاع الفيديو»)؛ يُطبَّق عند الإخراج النهائي، ويجب إعادة تشغيل الانتقالات للمونتاج الموجود",
"渲染集尾预览小片:末组尾 2s + 收束,与成片同一滤镜链": "تصيير معاينة الإغلاق: آخر ثانيتين من المجموعة الأخيرة + الإغلاق، بسلسلة المرشحات نفسها للمونتاج النهائي",
// NSFW 模式(设置→高级;index.html 弹窗 + preview_storyboard.html 组卡 🔞)
"NSFW 模式": "وضع NSFW",
"NSFW 模式:默认关;开启后可为语言/图像/视频分别指定备用模型,标记 NSFW 的工单与分镜组自动改走备用模型,主渠道内容审核拒收时自动切换重提一次": "وضع NSFW: معطّل افتراضياً؛ عند تفعيله يمكن تعيين نموذج احتياطي مستقل لكل من اللغة/الصورة/الفيديو، وتُحوَّل البطاقات والمجموعات المعلَّمة NSFW تلقائياً إلى النماذج الاحتياطية، وعند رفض المزوّد الرئيسي للمحتوى في المراجعة يتم التبديل تلقائياً وإعادة الإرسال مرة واحدة",
"🔞 NSFW 模式": "🔞 وضع NSFW",
"启用 NSFW 模式": "تفعيل وضع NSFW",
"默认关。开启后可分别指定三类「备用模型」;派单与出图/出片按三层路由决定何时改用备用模型:① 显式标记优先——工单带 nsfw: true(总制片按剧本拆解表事件 content_flags → 分镜组 nsfw 推导,或你在分镜预览组卡点 🔞 手动标记)首次派单即走备用模型;② 兜底——主渠道返回内容审核拒收时,genmedia 同一调用内改备用渠道重提一次(不计重跑次数)并把该组记为 NSFW,后续不再先撞主模型;语言模型被拒不做进程内切换,同一 task_id 重派时改用备用语言模型。本模式只决定用哪套模型,不放宽内容安全审核与平台分级。": "معطّل افتراضياً. عند تفعيله يمكن تعيين «نموذج احتياطي» لكل نوع من الأنواع الثلاثة؛ ويقرر الإرسال وتوليد الصور/الفيديو متى يُستخدم الاحتياطي عبر ثلاث طبقات: ① العلامة الصريحة أولاً — البطاقة التي تحمل nsfw: true (يستنتج المنتج العام nsfw للمجموعة من content_flags للأحداث في جدول تفكيك السيناريو، أو تعلّمها يدوياً بالضغط على 🔞 في بطاقة المجموعة بمعاينة الستوري بورد) تذهب إلى النموذج الاحتياطي من أول إرسال؛ ② شبكة الأمان — عندما يُرجع المزوّد الرئيسي رفضاً من مراجعة المحتوى، يعيد genmedia الإرسال مرة واحدة إلى المزوّد الاحتياطي ضمن نفس الاستدعاء (لا يُحسب ضمن مرات الإعادة) ويسجّل المجموعة كـ NSFW فلا تصطدم بالنموذج الرئيسي أولاً بعد ذلك؛ أما نموذج اللغة المرفوض فلا يُبدَّل داخل العملية، بل يُستخدم نموذج اللغة الاحتياطي عند إعادة إرسال نفس task_id. يحدد هذا الوضع مجموعة النماذج المستخدمة فقط؛ ولا يخفف مراجعة سلامة المحتوى أو تصنيفات المنصات.",
"图像模型": "نموذج الصورة",
"渠道须已在「🎨 生成模型」页配好 Key(未配置的置灰);留「不设置」= 该类不切换,照常走主模型。ComfyUI 的二级选项是运行方式。备用渠道不可用时不会偷跑主模型,而是报错交你裁决。": "يجب أن يكون Key المزوّد مضبوطاً مسبقاً في صفحة «🎨 نماذج التوليد» (غير المضبوط يظهر باهتاً)؛ ترك «غير محدد» = هذا النوع لا يتبدّل ويستمر على النموذج الرئيسي كالمعتاد. في ComfyUI الخيار من المستوى الثاني هو وضع التشغيل. عند عدم توفر المزوّد الاحتياطي لا يُشغَّل النموذج الرئيسي خلسةً، بل يُبلَّغ عن خطأ لتقرر أنت.",
