"组边界的声桥(J/L-cut)默认值:声先入 = 下组声音提前压在本组尾画面上;声延续 = 本组声音拖过切点压在下组首画面上。承载「底床」= 只用去人声后的环境声预滚/延续,画面与口型不动;「画外台词」= 让切点旁的画外句跨切点,需声画分离开启且切点旁有画外句。电影感模式自动给建议,自定义模式按「边界处理」里的声先入/声延续出,极简模式不出;每处可在分镜预览页过场卡改": "القيمة الافتراضية لجسور الصوت عند حدود المجموعات (J/L-cut): تقدّم الصوت = صوت المجموعة التالية يدخل مبكرًا فوق الصورة الأخيرة لهذه المجموعة؛ امتداد الصوت = صوت هذه المجموعة يستمر بعد القطع فوق أول صورة في التالية. «الخلفية» = فقط الصوت المحيط بعد إزالة الأصوات يتقدّم/يمتد والصورة وحركة الشفاه ثابتة؛ «سطر خارج الكادر» = سطر خارج الكادر بجوار القطع يعبره، ويتطلب تفعيل الفصل ووجود ذلك السطر. الوضع السينمائي يقترح تلقائيًا، والمخصص يتبع اختيار «معالجة الحدود»، والبسيط لا يُخرجه؛ يمكن تغيير كل حد في بطاقة الانتقال بصفحة معاينة الستوري بورد",
"音先入": "تقدم الصوت (J-cut)",

