"人物台词可以不在画内开口:画外 O.S.(说话人在场但不入画)/ V.O.(内心独白、读信、回忆声)。画外句在后期按该人物声线合成,不进组视频生成。自动=剧本标记 + 分镜按白名单自动转画外;仅剧本标记=只认剧本写的 (O.S.)/(V.O.);关=全部台词画内开口。与旁白开关正交:旁白只管旁白者声线": "لا يلزم أن تُقال سطور الشخصيات داخل الكادر: خارج الكادر O.S. (حاضر لكن خارج الإطار) / V.O. (مونولوج داخلي، رسائل، أصوات مستذكرة). تُركَّب السطور خارج الكادر في مرحلة ما بعد الإنتاج بصوت الشخصية ولا تدخل في توليد فيديو المجموعة. تلقائي = علامات السيناريو + تحويل تلقائي في لوحة القصة وفق القائمة البيضاء؛ علامات السيناريو فقط = يُعتدّ فقط بـ (O.S.)/(V.O.) المكتوبة في السيناريو؛ إيقاف = كل السطور داخل الكادر. مستقل عن مفتاح السرد: السرد يحكم صوت الراوي فقط",
