"等总制片建签字单(本集全部组的视频提示词写完后自动);建好后这里出现「签字确认」按钮。签字前不生成本集组视频": "بانتظار أن ينشئ المنتج بطاقة الاعتماد (تلقائيًا بعد اكتمال كتابة موجّهات الفيديو لكل مجموعات الحلقة)؛ بعدها يظهر هنا زر «اعتماد». لا يُولَّد أي فيديو مجموعة لهذه الحلقة قبل الاعتماد",
